import Foundation

/// Speed Up Typing's Swift half (road map "creator-jobs" CU9b, spec §11 CU-91…CU-93): the
/// sheet's settings and their remembered keys, `plan_typing` asked of the core through
/// `ReelCursor` (this file names no `rc_*`, CJ-8 (l)) with its answer read into ops, and the
/// speech step — a media with sound under a stretch and no stored `speech` gets its spans from
/// its voice-activity cache, as Duck by Speech does, in the same undo step. Both doors —
/// Clip ▸ Speed Up Typing… (`SpeedUpTypingSheetController`) and `speed_up_typing`
/// (`AgentServer+SpeedUpTyping.swift`) — resolve here. The cursor files are found and read
/// through `AutoZoom.cursorFiles` and `AutoZoom.readTracks`.

/// What the sheet sets (CU-92's defaults; Keep pitch on is the owner's answer).
struct SpeedUpTypingSettings: Equatable {
    var rate = 4.0, shortest = 3.0, keepPitch = true

    static let rateRange: ClosedRange<Double> = 2...8
    static let shortestRange: ClosedRange<Double> = 1...30

    static let rateKey = "FrameJobSpeedUpTypingRate"
    static let shortestKey = "FrameJobSpeedUpTypingShortest"
    static let keepPitchKey = "FrameJobSpeedUpTypingKeepPitch"

    /// The remembered values, each clamped into its range; the default for a key not stored.
    /// Read through `double(forKey:)` and `bool(forKey:)`, so a launch argument's string
    /// (`-FrameJobSpeedUpTypingRate 6`) reads as its number.
    static func remembered(_ d: UserDefaults) -> SpeedUpTypingSettings {
        var s = SpeedUpTypingSettings()
        func number(_ key: String, _ range: ClosedRange<Double>, _ value: inout Double) {
            guard d.object(forKey: key) != nil else { return }
            let v = d.double(forKey: key)
            if v.isFinite, v > 0 { value = min(max(v, range.lowerBound), range.upperBound) }
        }
        number(rateKey, rateRange, &s.rate)
        number(shortestKey, shortestRange, &s.shortest)
        if d.object(forKey: keepPitchKey) != nil { s.keepPitch = d.bool(forKey: keepPitchKey) }
        return s
    }

    /// Writes only the keys whose value differs from `opened`'s, so a sheet whose controls
    /// were not changed writes nothing (mcp.py's DEFAULTS MOVED guard).
    func remember(changedFrom opened: SpeedUpTypingSettings, in d: UserDefaults) {
        if rate != opened.rate { d.set(rate, forKey: Self.rateKey) }
        if shortest != opened.shortest { d.set(shortest, forKey: Self.shortestKey) }
        if keepPitch != opened.keepPitch { d.set(keepPitch, forKey: Self.keepPitchKey) }
    }
}

/// `plan_typing`'s answer: the `retime_range` ops right to left, the counts, each range with
/// where its end lands, and the time saved.
struct SpeedUpTypingPlan {
    let ops: [ReelOp]
    let stretches, short: Int
    let ranges: [(from: Ticks, to: Ticks, spedTo: Ticks)]
    let saved: Ticks
}

/// The speech step's answer (CU-93): the `set_media_speech` ops to send first, the names of
/// media whose detection has not finished, or a sentence.
enum SpeedUpTypingSpeech: Equatable {
    case ready([ReelOp])
    case pending([String])
    case refused(String)

    static func == (a: SpeedUpTypingSpeech, b: SpeedUpTypingSpeech) -> Bool {
        switch (a, b) {
        case (.ready(let x), .ready(let y)): return x.map(\.json) == y.map(\.json)
        case (.pending(let x), .pending(let y)): return x == y
        case (.refused(let x), .refused(let y)): return x == y
        default: return false
        }
    }
}

/// What `resolve` answers: a plan with the speech ops it needs first, or the media waited for.
enum SpeedUpTypingOutcome {
    case planned(speechOps: [ReelOp], plan: SpeedUpTypingPlan)
    case waiting([String])
}

enum SpeedUpTyping {
    /// The undo step's name, both doors.
    static let actionName = "Speed Up Typing"
    /// How long the sheet waits for speech detection (AU-68's bound, as
    /// `RecordingEnhance.waitLimit`).
    static let waitLimit: TimeInterval = 300

    /// Whether a wait of `elapsed` seconds has reached `waitLimit`.
    static func gaveUp(waitingFor elapsed: TimeInterval) -> Bool {
        elapsed >= waitLimit
    }

    /// A sentence either door shows as it is.
    struct Refusal: LocalizedError {
        let message: String
        var errorDescription: String? { message }
    }

    /// `plan_typing`'s request JSON for `clips` (container ticks `from`/`to`, nil for none).
    static func request(
        _ clips: [UInt32], settings: SpeedUpTypingSettings, from: Ticks?, to: Ticks?
    ) -> String {
        var args: [String: Any] = [
            "clips": clips.map { Int($0) }, "rate": settings.rate,
            "shortest": settings.shortest, "keep_pitch": settings.keepPitch,
        ]
        if let from { args["from"] = from }
        if let to { args["to"] = to }
        let data = (try? JSONSerialization.data(withJSONObject: ["plan_typing": args])) ?? Data()
        return String(decoding: data, as: UTF8.self)
    }

    /// The speech step for the media `plan_typing` named in `needs_speech` (CU-93), in order:
    /// a media whose `speech` is stored is skipped (AU-111); no file is refused; a current
    /// cache (`isCurrent`) that loads becomes a `set_media_speech` op; otherwise pending while
    /// detection is `available`, and refused when it is not.
    static func speech(
        for media: [UInt32], in snapshot: ProjectSnapshot, cacheDirectory: URL?,
        available: Bool, isCurrent: (MediaSnapshot) -> Bool
    ) -> SpeedUpTypingSpeech {
        var ops: [ReelOp] = []
        var pending: [String] = []
        for id in media {
            guard let m = snapshot.media(id), m.speech == nil else { continue }
            guard mediaURL(for: m) != nil else {
                return .refused("\(m.name) is offline, so its speech cannot be read.")
            }
            if isCurrent(m), let directory = cacheDirectory,
                let p = MediaImporter.loadSpeech(for: id, in: directory)
            {
                ops.append(.setMediaSpeech(media: id, spans: DuckSpeech.spans(p, duration: m.duration)))
            } else if available {
                pending.append(m.name)
            } else {
                return .refused(
                    "Speech detection is unavailable on this Mac, so Speed Up Typing cannot "
                        + "tell typing from talking.")
            }
        }
        return pending.isEmpty ? .ready(ops) : .pending(pending)
    }

    /// Whether `media`'s speech cache in `cacheDirectory` is current, its file stat'ed.
    static func cacheIsCurrent(_ media: MediaSnapshot, in cacheDirectory: URL?) -> Bool {
        guard let cacheDirectory, let url = mediaURL(for: media) else { return false }
        let stamp = MediaImporter.CacheStamp.stamp(for: media, url: url)
        return MediaImporter.speechIsCurrent(for: media, stamp: stamp, in: cacheDirectory)
    }

    /// Plans over `clips` of `project` (the edited one, so inside a nest the nest's), makes the
    /// speech ops it asks for, applies them to the pure handle and plans again; throws the
    /// core's sentence or the speech step's as a `Refusal`.
    static func resolve(
        _ clips: [ClipSnapshot], tracks: [UInt32: ReelCursor], project: ReelProject,
        cacheDirectory: URL?, settings: SpeedUpTypingSettings, from: Ticks?, to: Ticks?,
        available: Bool = SileroVAD.isAvailable
    ) throws -> SpeedUpTypingOutcome {
        let first = try plan(
            clips, tracks: tracks, project: project, settings: settings, from: from, to: to)
        guard !first.needs.isEmpty else { return .planned(speechOps: [], plan: first.plan) }
        let speechOps: [ReelOp]
        switch speech(
            for: first.needs, in: project.snapshot, cacheDirectory: cacheDirectory,
            available: available, isCurrent: { cacheIsCurrent($0, in: cacheDirectory) })
        {
        case .refused(let why): throw Refusal(message: why)
        case .pending(let names): return .waiting(names)
        case .ready(let ops): speechOps = ops
        }
        guard case .applied(let spoken)? = try? project.applying(speechOps) else {
            throw Refusal(message: "The speech spans could not be saved, so nothing was sped up.")
        }
        let second = try plan(
            clips, tracks: tracks, project: spoken, settings: settings, from: from, to: to)
        guard second.needs.isEmpty else {
            throw Refusal(message: "The speech spans could not be saved, so nothing was sped up.")
        }
        return .planned(speechOps: speechOps, plan: second.plan)
    }

    /// Asks the core for the plan, one track per clip; the media it needs speech for, and the
    /// plan (empty while any are needed).
    private static func plan(
        _ clips: [ClipSnapshot], tracks: [UInt32: ReelCursor], project: ReelProject,
        settings: SpeedUpTypingSettings, from: Ticks?, to: Ticks?
    ) throws -> (needs: [UInt32], plan: SpeedUpTypingPlan) {
        var ordered: [ReelCursor] = []
        for clip in clips {
            guard case .media(let id, _, _) = clip.source, let track = tracks[id] else {
                throw Refusal(message: "Clip \(clip.id)'s cursor file was not read.")
            }
            ordered.append(track)
        }
        let text: String
        do {
            text = try ReelCursor.query(
                request(clips.map(\.id), settings: settings, from: from, to: to),
                tracks: ordered, project: project)
        } catch {
            let reason = (error as? ReelCoreError)?.message ?? error.localizedDescription
            throw Refusal(message: AutoZoom.sentence(reason))
        }
        guard let answer = try? JSONSerialization.jsonObject(with: Data(text.utf8))
            as? [String: Any]
        else { throw Refusal(message: "Speed Up Typing's plan could not be read.") }
        func number(_ o: [String: Any], _ key: String) -> Int64 {
            (o[key] as? NSNumber)?.int64Value ?? 0
        }
        let ops = try ((answer["ops"] as? [[String: Any]]) ?? []).map { o -> ReelOp in
            guard o["op"] as? String == "retime_range" else {
                throw Refusal(message: "Speed Up Typing's plan named an op it does not make.")
            }
            return .retimeRange(
                from: number(o, "from"), to: number(o, "to"),
                rate: (o["rate"] as? NSNumber)?.doubleValue ?? settings.rate,
                keepPitch: (o["keep_pitch"] as? Bool) ?? settings.keepPitch)
        }
        let ranges = ((answer["ranges"] as? [[String: Any]]) ?? []).map {
            (from: number($0, "from"), to: number($0, "to"), spedTo: number($0, "sped_to"))
        }
        let needs = ((answer["needs_speech"] as? [NSNumber]) ?? []).map(\.uint32Value)
        return (
            needs,
            SpeedUpTypingPlan(
                ops: ops, stretches: Int(number(answer, "stretches")),
                short: Int(number(answer, "short")), ranges: ranges,
                saved: number(answer, "saved"))
        )
    }

    /// The sheet's summary: what Apply would do, or why it would change nothing.
    static func summary(_ plan: SpeedUpTypingPlan, settings: SpeedUpTypingSettings) -> String {
        guard !plan.ops.isEmpty else {
            return "No typing stretch without speech or a shortcut lasts "
                + "\(plain(settings.shortest)) s or more in the selected clips, so nothing "
                + "would change."
        }
        let n = plan.ops.count
        let stretches = n == 1 ? "1 typing stretch" : "\(n) typing stretches"
        let seconds = String(format: "%.1f", Double(plan.saved) / Double(ReelTime.perSecond))
        return "\(stretches) sped up ×\(plain(settings.rate)), saving \(seconds) s."
    }

    /// A number with no ".0" on a whole one.
    static func plain(_ v: Double) -> String {
        v.rounded() == v && abs(v) < 1e15 ? String(Int64(v)) : String(format: "%g", v)
    }
}

//! `plan_typing`, Speed Up Typing's planner (road map creator-jobs CU9b,
//! spec §11 CU-91, CU-92): the selected clips' typing stretches in container
//! time, less every span of speech under them and every shortcut's overlay,
//! united across the clips, kept when they last `shortest`, trimmed by a
//! 0.3 s margin at ×1 at each end, and answered as `retime_range` ops (CU-90)
//! right to left, so no op moves the range of one still to come. The ops are
//! tried on a clone first: the plan is applied whole or refused whole.
//! Nothing here edits the project it is given.

use std::collections::BTreeSet;

use serde::Deserialize;
use serde_json::{json, Value};

use crate::audio_duck_speech::speech_in_clip;
use crate::cursor_bursts::typing_stretches;
use crate::cursor_overlays::{DEFAULT_DURATION, MOST_LATE, TRACK_NAME};
use crate::cursor_track::{us_to_ticks, CursorTrack};
use crate::cursor_zoom_run::{clip_time, end, media_in};
use crate::model::{Clip, Project, Source};
use crate::outcome::Outcome;
use crate::time::{seconds_to_ticks, Ticks};

/// Seconds kept at ×1 at each end of a sped stretch (CU-92).
pub(crate) const MARGIN: f64 = 0.3;
/// `rate`'s range (CU-92).
pub(crate) const RATE_RANGE: (f64, f64) = (2.0, 8.0);
/// `shortest`'s range, seconds (CU-92).
pub(crate) const SHORTEST_RANGE: (f64, f64) = (1.0, 30.0);

fn default_rate() -> f64 {
    4.0
}

fn default_shortest() -> f64 {
    3.0
}

fn default_keep_pitch() -> bool {
    true
}

/// `plan_typing`'s request (CU-92); `shortest` in seconds, `from` and `to`
/// container ticks.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct PlanTypingArgs {
    #[serde(default)]
    pub clips: Vec<u32>,
    #[serde(default = "default_rate")]
    pub rate: f64,
    #[serde(default = "default_shortest")]
    pub shortest: f64,
    #[serde(default = "default_keep_pitch")]
    pub keep_pitch: bool,
    #[serde(default)]
    pub from: Option<Ticks>,
    #[serde(default)]
    pub to: Option<Ticks>,
}

/// Checks every clip in CU-92's order.
fn check(project: &Project, clips: &[u32]) -> Result<(), String> {
    for (i, &id) in clips.iter().enumerate() {
        if clips[..i].contains(&id) {
            return Err(format!("clip {id} is named twice"));
        }
        let clip = project.require_clip(id)?;
        let Source::Media {
            media, reversed, ..
        } = &clip.source
        else {
            return Err(format!("clip {id} is not a media clip"));
        };
        if project
            .media(*media)
            .and_then(|m| m.cursor.as_ref())
            .is_none()
        {
            return Err(format!("clip {id}'s media {media} has no cursor file"));
        }
        if *reversed {
            return Err(format!(
                "clip {id} plays reversed; Speed Up Typing speeds only clips that play forward"
            ));
        }
    }
    Ok(())
}

/// A source tick `s` of `clip` in container time, when inside its played
/// window `[in, in + content_length_in_source)` (CU8's mapping, through S).
fn played_at(project: &Project, clip: &Clip, s: Ticks) -> Option<Ticks> {
    let (_, source_in) = media_in(clip)?;
    let length = project.content_length_in_source(clip);
    (source_in <= s && s < source_in.saturating_add(length))
        .then(|| clip.start.saturating_add(clip_time(clip, s - source_in)))
}

/// CU-91 (1): `clip`'s typing stretches, clamped to its played window, in
/// container time, inside `window`.
fn stretches_of(
    project: &Project,
    clip: &Clip,
    track: &CursorTrack,
    window: (Ticks, Ticks),
) -> Vec<(Ticks, Ticks)> {
    let Some((_, source_in)) = media_in(clip) else {
        return Vec::new();
    };
    let source_end = source_in.saturating_add(project.content_length_in_source(clip));
    let mut out = Vec::new();
    for (first, last, _) in typing_stretches(&track.file().keys.typed.t) {
        let (s0, s1) = (us_to_ticks(first).max(source_in), us_to_ticks(last));
        let s1 = s1.min(source_end);
        if s1 <= s0 {
            continue;
        }
        let at = |s: Ticks| clip.start.saturating_add(clip_time(clip, s - source_in));
        let (a, b) = (at(s0).max(window.0), at(s1).min(window.1));
        if b > a {
            out.push((a, b));
        }
    }
    out
}

/// CU-91 (2b): every recorded shortcut's overlay span for `clip`, with no
/// `[from, to)` filter on the presses.
fn overlay_spans(project: &Project, clip: &Clip, track: &CursorTrack) -> Vec<(Ticks, Ticks)> {
    let shortcuts: BTreeSet<u32> = project
        .tracks
        .iter()
        .filter(|t| t.name == TRACK_NAME)
        .map(|t| t.id)
        .collect();
    let late = seconds_to_ticks(MOST_LATE);
    let fallback = seconds_to_ticks(DEFAULT_DURATION);
    let mut out = Vec::new();
    for &t in &track.file().keys.shortcut.t {
        let Some(p) = played_at(project, clip, us_to_ticks(t)) else {
            continue;
        };
        let before = out.len();
        for c in project
            .clips
            .iter()
            .filter(|c| shortcuts.contains(&c.track))
        {
            let holds = c.start <= p && p < end(c);
            let soon = p < c.start && c.start <= p.saturating_add(late);
            if holds || soon {
                out.push((p.min(c.start), end(c)));
            }
        }
        if out.len() == before {
            out.push((p, p.saturating_add(fallback)));
        }
    }
    out
}

/// `piece` less every span of `cuts`.
fn subtract(piece: (Ticks, Ticks), cuts: &[(Ticks, Ticks)]) -> Vec<(Ticks, Ticks)> {
    let mut left = vec![piece];
    for &(c0, c1) in cuts {
        left = left
            .into_iter()
            .flat_map(|(a, b)| {
                if c1 <= a || b <= c0 {
                    return vec![(a, b)];
                }
                [(a, c0.min(b)), (c1.max(a), b)]
                    .into_iter()
                    .filter(|(x, y)| y > x)
                    .collect()
            })
            .collect();
    }
    left
}

/// Pieces sorted and merged where they overlap or touch (CU-91 (3)).
fn united(mut pieces: Vec<(Ticks, Ticks)>) -> Vec<(Ticks, Ticks)> {
    pieces.sort_unstable();
    let mut out: Vec<(Ticks, Ticks)> = Vec::with_capacity(pieces.len());
    for (a, b) in pieces {
        match out.last_mut() {
            Some(last) if a <= last.1 => last.1 = last.1.max(b),
            _ => out.push((a, b)),
        }
    }
    out
}

/// Answers `plan_typing` (CU-91, CU-92) against `tracks`, one per clip.
pub(crate) fn plan_typing(
    tracks: &[&CursorTrack],
    project: &Project,
    args: PlanTypingArgs,
) -> Result<Value, String> {
    let (lo, hi) = RATE_RANGE;
    if !(args.rate.is_finite() && (lo..=hi).contains(&args.rate)) {
        return Err(format!("rate is ×{}; it runs ×{lo}–×{hi}", args.rate));
    }
    let (lo, hi) = SHORTEST_RANGE;
    if !(args.shortest.is_finite() && (lo..=hi).contains(&args.shortest)) {
        return Err(format!(
            "shortest is {} s; it runs {lo}–{hi}",
            args.shortest
        ));
    }
    if let (Some(from), Some(to)) = (args.from, args.to) {
        if to <= from {
            return Err(format!("to ({to}) must be after from ({from})"));
        }
    }
    if args.clips.is_empty() {
        return Err("plan_typing needs at least one clip".into());
    }
    if tracks.len() != args.clips.len() {
        return Err(format!(
            "plan_typing reads one cursor track per clip; {} clips and {} tracks were given",
            args.clips.len(),
            tracks.len()
        ));
    }
    check(project, &args.clips)?;
    let window = (
        args.from.unwrap_or(Ticks::MIN),
        args.to.unwrap_or(Ticks::MAX),
    );
    let mut stretches: Vec<(Ticks, Ticks)> = Vec::new();
    let mut overlays: Vec<(Ticks, Ticks)> = Vec::new();
    for (i, &id) in args.clips.iter().enumerate() {
        let clip = project.require_clip(id)?;
        stretches.extend(stretches_of(project, clip, tracks[i], window));
        overlays.extend(overlay_spans(project, clip, tracks[i]));
    }
    // CU-91 (2a): the speech of every media clip with sound under a stretch.
    let mut speech: Vec<(Ticks, Ticks)> = Vec::new();
    let mut needs: BTreeSet<u32> = BTreeSet::new();
    for c in &project.clips {
        let Source::Media { media: id, .. } = c.source else {
            continue;
        };
        let Some(media) = project.media(id).filter(|m| m.has_audio) else {
            continue;
        };
        if !stretches.iter().any(|&(a, b)| c.start < b && a < end(c)) {
            continue;
        }
        match &media.speech {
            None => {
                needs.insert(id);
            }
            Some(spans) => speech.extend(
                speech_in_clip(c, media, spans)
                    .into_iter()
                    .map(|(a, b)| (c.start.saturating_add(a), c.start.saturating_add(b))),
            ),
        }
    }
    if !needs.is_empty() {
        return Ok(json!({
            "ops": [], "needs_speech": needs.into_iter().collect::<Vec<u32>>(),
            "stretches": 0, "short": 0, "ranges": [], "saved": 0,
        }));
    }
    let cuts: Vec<(Ticks, Ticks)> = speech.into_iter().chain(overlays).collect();
    let pieces: Vec<(Ticks, Ticks)> = stretches
        .into_iter()
        .flat_map(|s| subtract(s, &cuts))
        .collect();
    let (shortest, margin) = (seconds_to_ticks(args.shortest), seconds_to_ticks(MARGIN));
    let mut short = 0;
    let mut ranges: Vec<(Ticks, Ticks)> = Vec::new();
    for (a, b) in united(pieces) {
        let (from, to) = (project.snapped(a + margin), project.snapped(b - margin));
        if b - a < shortest || to <= from {
            short += 1;
            continue;
        }
        ranges.push((from, to));
    }
    let sped_to = |(from, to): (Ticks, Ticks)| {
        let scaled = ((to - from) as f64 / args.rate).round() as Ticks;
        project.snapped(from.saturating_add(scaled))
    };
    // All or nothing (CU-91 (5)): every op tried in order on a clone.
    let mut trial = project.clone();
    let mut ops: Vec<Value> = Vec::new();
    for &(from, to) in ranges.iter().rev() {
        let refused =
            |why: String| format!("the typing from {from} to {to} ticks cannot be sped up: {why}");
        match trial.retime_range(from, to, args.rate, Some(args.keep_pitch)) {
            Ok(Outcome::Applied(next)) => trial = next,
            Ok(Outcome::Identity) => {}
            Ok(Outcome::Refused(why)) | Err(why) => return Err(refused(why)),
        }
        ops.push(json!({
            "op": "retime_range", "from": from, "to": to, "rate": args.rate,
            "keep_pitch": args.keep_pitch,
        }));
    }
    let saved: Ticks = ranges.iter().map(|&r| r.1 - sped_to(r)).sum();
    let answered: Vec<Value> = ranges
        .iter()
        .map(|&r| json!({"from": r.0, "to": r.1, "sped_to": sped_to(r)}))
        .collect();
    Ok(json!({
        "ops": ops, "needs_speech": [], "stretches": ranges.len(), "short": short,
        "ranges": answered, "saved": saved,
    }))
}
//! Bursts of input in a cursor file (spec §11 CU-25, CU-70): the typing
//! stretches an `events` request answers and Auto Zoom anchors on, and the
//! scroll bursts that end an Auto Zoom visit, by CU7's figures. CU9b reads
//! the same stretches. Both are one run finder with their own figures.

/// Marks closer than this belong to one stretch (strictly under 1.0 s).
pub const TYPING_GAP_US: i64 = 1_000_000;
/// The fewest marks a stretch holds.
pub const TYPING_MIN_MARKS: usize = 3;
/// Wheel events closer than this belong to one burst (strictly under 1.0 s).
pub const SCROLL_GAP_US: i64 = 1_000_000;
/// The fewest wheel events a burst holds.
pub const SCROLL_MIN_EVENTS: usize = 3;

/// Each run of `t` (µs, in order) whose neighbours are less than `gap`
/// apart and which holds at least `min` entries, as (first, last, count).
fn runs(t: &[i64], gap: i64, min: usize) -> Vec<(i64, i64, usize)> {
    let mut out = Vec::new();
    let mut start = 0;
    for i in 1..=t.len() {
        if i == t.len() || t[i] - t[i - 1] >= gap {
            if i - start >= min {
                out.push((t[start], t[i - 1], i - start));
            }
            start = i;
        }
    }
    out
}

/// The typing stretches of `t` (the `typed` marks' µs, in order): each run
/// of marks less than `TYPING_GAP_US` apart holding at least
/// `TYPING_MIN_MARKS`, as (first mark, last mark, marks).
pub(crate) fn typing_stretches(t: &[i64]) -> Vec<(i64, i64, usize)> {
    runs(t, TYPING_GAP_US, TYPING_MIN_MARKS)
}

/// The scroll bursts of `t` (the `scrolls`' µs, in order): each run of
/// wheel events less than `SCROLL_GAP_US` apart holding at least
/// `SCROLL_MIN_EVENTS`, as (first, last, events).
pub(crate) fn scroll_bursts(t: &[i64]) -> Vec<(i64, i64, usize)> {
    runs(t, SCROLL_GAP_US, SCROLL_MIN_EVENTS)
}
import Foundation

/// `speed_up_typing` (road map "creator-jobs" CU9b, spec §11 CU-93) — mirrors Clip ▸ Speed Up
/// Typing… (`EditorViewController+SpeedUpTyping.swift`, `SpeedUpTypingSheetController`) through
/// the same `SpeedUpTyping.resolve`. An app-state composite of `set_media_speech` and
/// `retime_range`: no `scope` key (dispatch reads `scope` only for op names); it acts in the
/// container `set_scope` has open, as `auto_zoom` does. An agent is told in its answer what a
/// person is asked (`SpeedAudioDrop`'s note), as `retime_range`'s tool does.
extension AgentServer {

    /// What the first main-thread hop resolves.
    private struct SpeedUpTypingCall {
        let document: ProjectDocument
        let clips: [UInt32]
        let files: [UInt32: URL]
        let settings: SpeedUpTypingSettings
        let from: Ticks?
        let to: Ticks?
        let asked: ReelProject
        let scope: UInt32?
    }

    /// **Runs on the SERVER thread** (`creatorOffMainTools`): one main hop resolves the clips
    /// and their cursor files, the files are read here, and a last main hop refuses when the
    /// project or the scope changed meanwhile, resolves the plan and its speech step, and
    /// applies both as one undo step "Speed Up Typing". Writes its own tail rather than
    /// `editResult`'s: the crossing is read on `SpeedAudioDrop`'s baseline of the
    /// speech-applied handle BEFORE the edit, where a split half is not yet new.
    func speedUpTyping(_ a: [String: Any]) throws -> String {
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "speed_up_typing must run on the server thread — its name is missing "
                    + "from AgentServer.creatorOffMainTools.")
        }
        let call = try onMain { try self.resolveSpeedUpTyping(a) }
        return try runSpeedUpTyping(call)
    }

    /// The tool's body over `clips` of `document` with `settings` and no `from`/`to`: what
    /// `record_screen`'s polish on landing calls (road map "creator-jobs" CU10, spec §11
    /// CU-100). **SERVER THREAD**; one undo step "Speed Up Typing", answered as the tool
    /// answers (its "not detected yet" refusal included).
    func speedUpTyping(
        document: ProjectDocument, clips: [UInt32], settings: SpeedUpTypingSettings
    ) throws -> String {
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "speed_up_typing must run on the server thread — its name is missing "
                    + "from AgentServer.creatorOffMainTools.")
        }
        let call = try onMain {
            try self.speedUpTypingCall(document, clips, settings: settings, from: nil, to: nil)
        }
        return try runSpeedUpTyping(call)
    }

    /// Both forms' body after the first hop: the files read here, then the last main hop.
    private func runSpeedUpTyping(_ call: SpeedUpTypingCall) throws -> String {
        let tracks: [UInt32: ReelCursor]
        do {
            tracks = try AutoZoom.readTracks(call.files)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        return try onMain {
            let document = call.document
            guard document.project === call.asked, document.scope == call.scope else {
                throw ToolError(
                    message: "the project changed while speed_up_typing read the cursor "
                        + "files, so nothing was sped up. Call speed_up_typing again.")
            }
            let snapshot = document.editedProject.snapshot
            let clips = call.clips.compactMap { snapshot.clip($0) }
            let outcome: SpeedUpTypingOutcome
            do {
                outcome = try SpeedUpTyping.resolve(
                    clips, tracks: tracks, project: document.editedProject,
                    cacheDirectory: document.cacheDirectory, settings: call.settings,
                    from: call.from, to: call.to)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
            switch outcome {
            case .waiting(let names):
                // A pass that could not read a file is not retried until the next open, so
                // the door that sees pending starts it (idempotent).
                document.generateCaches()
                throw ToolError(
                    message: "\(names.joined(separator: ", "))'s speech has not been detected "
                        + "yet. Try again in a moment.")
            case .planned(let speechOps, let plan):
                return try self.applySpeedUpTyping(
                    document, speechOps: speechOps, plan: plan, shortest: call.settings.shortest)
            }
        }
    }

    /// The edit and its answer, on main.
    private func applySpeedUpTyping(
        _ document: ProjectDocument, speechOps: [ReelOp], plan: SpeedUpTypingPlan,
        shortest: Double
    ) throws -> String {
        let ranges: [[String: Any]] = plan.ranges.map {
            ["from": $0.from, "to": $0.to, "sped_to": $0.spedTo]
        }
        var result: [String: Any] = [
            "ok": true, "stretches": plan.stretches, "short": plan.short, "ranges": ranges,
            "saved": plan.saved,
        ]
        guard !plan.ops.isEmpty else {
            result["note"] = "no typing stretch without speech or a shortcut lasted "
                + "\(SpeedUpTyping.plain(shortest)) s or more in the clips' played windows, "
                + "so nothing was changed"
            result["project"] = summary(document)
            return try jsonResult(result)
        }
        let ops = speechOps + plan.ops
        let landing = scopeLanding(ops, document)
        let edited =
            effectiveScope(document).flatMap { document.project.scoped($0) } ?? document.project
        let spoken = (try? edited.applying(speechOps))?.project ?? edited
        let crossing = SpeedAudioDrop.crossing(applying: plan.ops, to: spoken)
        let before = try performGroupedEdit(document, SpeedUpTyping.actionName, ops)
        result["speech_saved"] = speechOps.compactMap { ($0.args["media"] as? UInt32).map(Int.init) }
        result.merge(Self.created(from: before, to: document.project.snapshot)) { _, new in new }
        result.merge(SpeedAudioDrop.answerFields(crossing)) { _, new in new }
        result.merge(landing) { _, new in new }
        result["project"] = summary(document)
        return try jsonResult(result)
    }

    /// Exactly one of `clip` and `clips`; then `from`/`to` and each clip's cursor file. The
    /// rate's and shortest's ranges are the core's refusals (CU-92).
    private func resolveSpeedUpTyping(_ a: [String: Any]) throws -> SpeedUpTypingCall {
        func given(_ key: String) -> Bool { a[key] != nil && !(a[key] is NSNull) }
        guard given("clip") != given("clips") else {
            throw ToolError(
                message: "Name exactly one of clip and clips: the screen recording clip, or "
                    + "the clips, whose typing to speed up.")
        }
        var settings = SpeedUpTypingSettings()
        settings.rate = try doubleArg(a, "rate") ?? settings.rate
        settings.shortest = try doubleArg(a, "shortest") ?? settings.shortest
        settings.keepPitch = try boolArg(a, "keep_pitch") ?? settings.keepPitch
        let from = try intArg(a, "from").map { Ticks($0) }
        let to = try intArg(a, "to").map { Ticks($0) }
        let document = try target(a)
        let ids =
            given("clip") ? [try clipArg(a, "clip", document).id] : try clipsArg(a, "clips", document)
        return try speedUpTypingCall(document, ids, settings: settings, from: from, to: to)
    }

    /// The clips' cursor files and the handle the last hop compares. Main.
    private func speedUpTypingCall(
        _ document: ProjectDocument, _ ids: [UInt32], settings: SpeedUpTypingSettings,
        from: Ticks?, to: Ticks?
    ) throws -> SpeedUpTypingCall {
        let snapshot = document.editedProject.snapshot
        let clips = ids.compactMap { snapshot.clip($0) }
        let files: [UInt32: URL]
        do {
            files = try AutoZoom.cursorFiles(clips, in: snapshot)
        } catch {
            throw ToolError(message: error.localizedDescription)
        }
        return SpeedUpTypingCall(
            document: document, clips: ids, files: files, settings: settings, from: from,
            to: to, asked: document.project, scope: document.scope)
    }
}
import AppKit

/// Clip ▸ Speed Up Typing… (road map "creator-jobs" CU9b, spec §11 CU-93): the selected clips of
/// the container being edited — the timeline, or the open nest — put up in
/// `SpeedUpTypingSheetController`, whose Apply commits the speech ops and `plan_typing`'s
/// `retime_range` ops through `SpeedAudioDrop.commit` as one undo step. `speed_up_typing`
/// mirrors it (`AgentServer+SpeedUpTyping.swift`). On-device, so no `ModelKeys` row (CJ-3).
extension EditorViewController {

    /// The selected clips the menu offers Speed Up Typing on, in id order; empty when any of
    /// them is not a media clip whose media has a cursor file (`AutoZoom.canOffer`).
    private func speedUpTypingClips(_ document: ProjectDocument) -> [UInt32] {
        let snapshot = document.editedProject.snapshot
        let clips = document.selection.sorted().compactMap { snapshot.clip($0) }
        guard clips.count == document.selection.count,
            AutoZoom.canOffer(clips, in: snapshot)
        else { return [] }
        return clips.map(\.id)
    }

    @objc func showSpeedUpTypingSheet(_ sender: Any?) {
        guard let document, view.window?.attachedSheet == nil else {
            NSSound.beep()
            return
        }
        let clips = speedUpTypingClips(document)
        guard !clips.isEmpty else {
            NSSound.beep()
            return
        }
        presentAsSheet(SpeedUpTypingSheetController(document: document, clips: clips))
    }

    /// The menu arm, answered from `validateUserInterfaceItem`'s default case; nil for any
    /// other action. On with at least one selected clip, each a media clip whose media has a
    /// cursor file, and no sheet on the window; allowed inside a nest.
    func validateSpeedUpTypingAction(_ action: Selector) -> Bool? {
        guard action == #selector(showSpeedUpTypingSheet(_:)) else { return nil }
        guard let document, view.window?.attachedSheet == nil else { return false }
        return !speedUpTypingClips(document).isEmpty
