    static func mayRetime(_ ops: [ReelOp]) -> Bool {
        ops.contains {
            ["set_speed", "rate_stretch", "add_speed_ramp", "set_action", "remove_action"]
                .contains($0.name)
                || ($0.name == "set_action_end"
