/// The calls a press of Record makes about the four grants, as values a
/// probe can replace: the reads, the four system prompts, the two remembered
/// "asked" flags and the one opener of System Settings. `live` is the app's;
/// `tools/proof/recording_probe.py` puts a sealed spy in
/// `RecorderPanelController.grantDoors` before any mode runs, so no probe
/// can prompt, open Settings or touch the key. Input Monitoring's four
/// (road map creator-jobs CU6, spec §11 CU-62) come last and default INERT —
/// never granted, never asking, never remembering — so a probe that fills
/// only the first ten compiles unchanged and can never prompt.
struct RecorderGrantDoors {
    /// Whether the panel has put up the Screen Recording prompt once
    /// (spec §11 recording). Written only by a launchd-owned press.
    static let screenRecordingAskedKey = "FrameJobScreenRecordingAsked"
    /// Whether the panel has asked for Input Monitoring once (spec §11 CU-3,
    /// CU-62). Written only by a launchd-owned press.
    static let inputMonitoringAskedKey = "FrameJobInputMonitoringAsked"

    var screenGranted: () -> Bool
    var launchedByLaunchd: () -> Bool
    var requestScreen: () -> Void
    var screenAsked: () -> Bool
    var rememberScreenAsked: () -> Void
    var microphoneStatus: () -> AVAuthorizationStatus
    var requestMicrophone: (@escaping () -> Void) -> Void
    var openSettings: (URL) -> Bool
    /// The Camera grant (CR1c, spec §11 CAM-5), asked only for Source Camera.
    var cameraStatus: () -> AVAuthorizationStatus
    var requestCamera: (@escaping () -> Void) -> Void
    /// Input Monitoring (CU-62), read only with Record shortcuts on.
    var inputMonitoringGranted: () -> Bool = { false }
    var requestInputMonitoring: () -> Void = {}
    var inputMonitoringAsked: () -> Bool = { false }
    var rememberInputMonitoringAsked: () -> Void = {}

    static var live: RecorderGrantDoors {
        RecorderGrantDoors(
            screenGranted: { RecordingGrant.screenRecordingGranted },
            launchedByLaunchd: { RecordingGrant.launchedByLaunchd },
            requestScreen: { _ = CGRequestScreenCaptureAccess() },
            screenAsked: { UserDefaults.standard.bool(forKey: screenRecordingAskedKey) },
            rememberScreenAsked: { UserDefaults.standard.set(true, forKey: screenRecordingAskedKey) },
            microphoneStatus: { RecordingGrant.microphoneStatus },
            requestMicrophone: { answered in
                // The framework does not say which queue it answers on, so
                // the answer hops to main.
                AVCaptureDevice.requestAccess(for: .audio) { _ in
                    DispatchQueue.main.async { answered() }
                }
            },
            openSettings: { url in NSWorkspace.shared.open(url) },
            cameraStatus: { RecordingGrant.cameraStatus },
            requestCamera: { answered in
                // As the microphone's: the answer hops to main.
                AVCaptureDevice.requestAccess(for: .video) { _ in
                    DispatchQueue.main.async { answered() }
                }
            },
            inputMonitoringGranted: { RecordingGrant.inputMonitoringGranted },
            requestInputMonitoring: { _ = CGRequestListenEventAccess() },
            inputMonitoringAsked: { UserDefaults.standard.bool(forKey: inputMonitoringAskedKey) },

    /// The sentence for a `stop()` that did not conclude within
    /// `stopCeiling(segments:camera:)`: it names every movie the recorder still
    /// holds — one per segment, the recording may finish on its own after
    /// the tool has answered, and a person can then import them — and the
    /// alert clause. Empty means the recorder no longer holds a session at
    /// all. The seconds it spells are the ceiling over `movies.count`, which
    /// is the number the wait used: the same count while the session is
    /// held (a stop removes no segment), and the one-segment number — the
    /// wait's own `?? 1` — when the recorder had let the session go. A
    /// voice-over's files are named "file", not "movie". `cameras` are the
    /// camera files beside a screen's movies (spec §11 CAM-10 (7)), named
    /// after them. `camera` is the wait's own `cameraBeside`, so the ceiling
    /// spelled is the one the wait used — with the camera's probe whenever a
    /// camera was asked for beside the screen, even when no camera file is
    /// held (CAM-11 (7)).
    static func finishTimeoutSentence(
        movies: [String], cameras: [String] = [], camera: Bool = false, voiceOver: Bool = false
    ) -> String {
        let noun = voiceOver ? "file" : "movie"
        let where_: String
        switch movies.count {
        case 0:
            where_ =
                "The recorder no longer holds the session, so the recording may already have "
                + "finished without answering."
        case 1:
            where_ = "The recording may still finish on its own; its \(noun) is at \(movies[0])."
        default:
            where_ =
                "The recording may still finish on its own; its \(noun)s are at "
                + movies.joined(separator: ", ") + "."
        }
        let besideClause: String
        switch cameras.count {
        case 0: besideClause = ""
        case 1: besideClause = " Its camera file is at \(cameras[0])."
        default: besideClause = " Its camera files are at " + cameras.joined(separator: ", ") + "."
        }
        let ceiling = stopCeiling(segments: movies.count, camera: camera)
        return "record_screen asked the recorder to stop and it did not finish within "
            + "\(Int(ceiling)) s. " + where_ + besideClause + recordingAlertClause
    }

    /// A failure AFTER the recording landed on disk, as a `ToolError` naming
    /// the file(s): the placement's trial, the commit and the untitled
    /// document are the three throw sites, and every one of them is reached
    /// with the footage already written. The files are
    /// `RecordingResult.filesClause` — every segment's movie comma-joined,
    /// then every microphone file that landed — the one spelling the panel's
    /// note uses too; with one segment the sentence is byte for byte R1's,
    /// which `tools/proof/recording_proof.py` matches by shape. A segment
    /// left out as unreadable (#97) is named after it, its files too.
    static func savedButNotAdded(_ result: RecordingResult, _ error: any Error) -> ToolError {
        ToolError(
            message: "The recording was saved at \(result.filesClause) but could not "
                + "be added: " + sentence(of: error)
                + (result.unreadableNote.map { " " + $0 } ?? ""))
    }
}
