            setNote(CameraDevices.noCameraSentence)
            return
        }
        guard checkScreenRecordingGrant(), checkInputMonitoringGrant(),
            !cameraBesideSelected || checkCameraGrant(), checkMicrophoneGrant()
        else { return }
