/// tool's start never does (CAM-7 (7)), so through a tool's recording the
/// well reads "The camera is recording."
extension RecorderPanelController {
    static let previewGrantSentence = "The preview shows once Frame Job may use the camera."
    static let previewRecordingSentence = "The camera is recording."

    /// CAM-7 (3)'s rule. `grant` and `failure` are called only at their own
    /// steps.
    static func cameraPreviewStep(
        visible: Bool, cameraSource: Bool, phase: Phase, recorderIdle: Bool,
        recordingCamera: Bool, cameraChosen: Bool, grant: () -> AVAuthorizationStatus,
        failure: () -> String?
    ) -> CameraPreviewStep {
        guard visible, cameraSource else { return .off }
        if recordingCamera { return .recording }
        switch phase {
        case .countdown, .starting: return .prepared
        startGeneration += 1
        let generation = startGeneration
        launched = false
        phase = .starting
        // A voice-over has no lookup to bound (`+VoiceOver.swift`).
        if choice.source == .voiceOver { return launchVoiceOver(choice) }
        // Nor does a camera: the recorder's own arm ceiling bounds it.
        if choice.source == .camera { return launchCamera(choice) }
        startTimer?.invalidate()
        startTimer = Timer.scheduledTimer(
            withTimeInterval: ScreenRecorder.armCeiling, repeats: false
        ) { [weak self] _ in self?.armTimedOut(generation: generation) }
        if choice.source == .picked, let filter = pickedFilter {
            launch(filter: filter, choice: choice)
            return
        }
        ScreenRecorder.shareableContent { [weak self] outcome in
            guard let self, self.phase == .starting, generation == self.startGeneration else {
                return
