            switch outcome {
            case .failure(let error):
                self.startFailed(error)
            case .success(let content):
                do {
                    let filter = try ScreenRecorder.filter(
                        for: choice.source, in: content, excluding: exclusion)
                    self.launch(filter: filter, choice: choice)
                } catch {
                    self.startFailed(error)
                }
            }
        }
